// ACL policy of the packet-policy chain (pack 5.2, owner: agent A; docs/SECURITY_PACK.md §5, §7):
// `ip access-group <acl> in` filters every packet arriving on the interface (also packets for the router
// itself), `… out` every packet the router forwards out of it. Packets the router originates do not pass
// egress (Cisco community: outbound ACLs "do not filter traffic generated by the device itself",
// https://community.cisco.com/t5/wan-routing-and-switching/newbie-outbound-acl-is-not-enforced/m-p/597072).
// A deny drops the packet with ICMP 3/13 (administratively prohibited; IcmpResponder decides whether an
// error may be sent at all: never about ICMP errors or broadcasts). Matches count in extensions.aclCounters.
import type { AclBinding } from '../../../domain'
import { localizedMessage } from '../../../i18n/messageKeys'
import { AclMatcher } from '../../../net/AclMatcher'
import type { DeviceContext, EventBuilder, Ipv4Packet } from '../../contract'
import { type EgressPacket, type IngressPacket, PASS, type PacketPolicy, type PolicyVerdict } from '../PacketPolicy'
import { AclBindings } from './AclBindings'
import { AclPacketViews } from './AclPacketViews'
import { AclRuntime } from './AclRuntime'

type Direction = keyof AclBinding

export class AclPolicy implements PacketPolicy {
  ingress(ctx: DeviceContext, arrival: IngressPacket): PolicyVerdict {
    return AclPolicy.filter(ctx, arrival.interfaceId, 'in', arrival.packet, arrival.event)
  }

  egress(ctx: DeviceContext, departure: EgressPacket): PolicyVerdict {
    return AclPolicy.filter(ctx, departure.exitInterfaceId, 'out', departure.packet, departure.event)
  }

  private static filter(ctx: DeviceContext, interfaceId: string, direction: Direction, packet: Ipv4Packet, event: EventBuilder): PolicyVerdict {
    const name = AclBindings.of(ctx.device, interfaceId)?.[direction]
    if (name === undefined) return PASS(packet)
    const layer = 3
    const noteDirection = direction === 'in' ? 'in' : 'out'
    const params = { acl: name, direction, iface: interfaceId }
    const decision = AclMatcher.decide(AclBindings.list(ctx.device, name), AclPacketViews.of(packet))
    switch (decision.kind) {
      case 'noList':
        event.note(layer, noteDirection, localizedMessage('acl:notes.noEntries', params))
        return PASS(packet)
      case 'implicitDeny':
        event.note(layer, noteDirection, localizedMessage('acl:notes.implicitDeny', params))
        return { kind: 'drop', reason: 'aclDenied', icmp: 'adminProhibited' }
      case 'match': {
        AclRuntime.count(ctx, name, decision.seq)
        const permitted = decision.action === 'permit'
        event.note(layer, noteDirection, localizedMessage(permitted ? 'acl:notes.permitted' : 'acl:notes.denied', { ...params, seq: decision.seq }))
        return permitted ? PASS(packet) : { kind: 'drop', reason: 'aclDenied', icmp: 'adminProhibited' }
      }
    }
  }
}
